import { CheckCircle2, XCircle, AlertCircle } from "lucide-react";
import { Button } from "@/components/ui/button";

// ##################
// authored (generated by antigravity, Jun 24 2026 21:28 WITA)
// ##################

export interface QuizResultProps {
  score?: number | null;
  passingScore?: number;
  status: "passed" | "failed" | "pending_review" | "graded";
  onContinue: () => void;
  onRetry?: () => void;
}

export function QuizResult({
  score,
  passingScore = 70,
  status,
  onContinue,
  onRetry,
}: QuizResultProps) {
  const isPassed =
    status === "passed" ||
    (score !== undefined && score !== null && score >= passingScore);
  const isPending = status === "pending_review";

  return (
    <div className="flex flex-col items-center justify-center space-y-6 py-12 text-center">
      {isPassed ? (
        <div className="rounded-full bg-green-100 p-4 text-green-700">
          <CheckCircle2 className="h-16 w-16" />
        </div>
      ) : isPending ? (
        <div className="rounded-full bg-yellow-100 p-4 text-yellow-700">
          <AlertCircle className="h-16 w-16" />
        </div>
      ) : (
        <div className="rounded-full bg-red-100 p-4 text-red-700">
          <XCircle className="h-16 w-16" />
        </div>
      )}

      <div className="space-y-2">
        <h3 className="text-2xl font-bold">
          {isPassed
            ? "Selamat! Anda Lulus Ujian"
            : isPending
              ? "Ujian Menunggu Penilaian"
              : "Maaf, Anda Belum Lulus"}
        </h3>

        {!isPending && score !== undefined && score !== null && (
          <p className="text-muted-foreground">
            Nilai Anda:{" "}
            <span className="font-bold text-foreground">{score}</span> (Minimal
            lulus: {passingScore})
          </p>
        )}

        {isPending && (
          <p className="text-muted-foreground">
            Ujian ini mengandung soal esai yang harus dinilai secara manual oleh
            instruktur/admin. Silakan tunggu hingga penilaian selesai.
          </p>
        )}
      </div>

      <div className="flex items-center space-x-4 pt-4">
        {!isPassed && !isPending && onRetry && (
          <Button variant="outline" onClick={onRetry}>
            Coba Lagi
          </Button>
        )}
        <Button onClick={onContinue}>
          {isPassed || isPending ? "Lanjut" : "Kembali"}
        </Button>
      </div>
    </div>
  );
}
